stItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "重点掌握高频题型（工程、行程、排列组合）"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "考试时先做数量关系中简单的题，难题放最后"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "数量关系不需要全对，抓住高频题型即可。建议重点练习工程、行程、排列组合。"}]}]}]}$$ AS jsonb), NULL, '行测-数量关系总览模块概述。', category_node.id, CAST('["数量关系总览"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
